pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.prank(address(c.owner()));
        c.transferOwnership(alice);
        vm.prank(alice);
        c.acceptOwnership();
        vm.prank(alice);
        c.transferOwnership(bob);
        vm.prank(bob);
        c.acceptOwnership();
        bool ok;
        vm.prank(alice);
        try c.acceptOwnership() { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
